style.css:
@-moz-document domain("x.com") {
@keyframes auroraMove {
    0% { 
      filter: hue-rotate(0deg); 
      transform: scale(1);
    }
    50% { 
      filter: hue-rotate(360deg); 
      transform: scale(1.08);
    }
    100% { 
      filter: hue-rotate(0deg); 
      transform: scale(1);
    }
  }

  /* 1. HAREKETLİ ARKA PLAN (Resimlere/videolara etki etmeyen izole katman) */
  body::before {
    content: "" !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background-image: 
      radial-gradient(circle at top left, #140421 0%, transparent 70%),
      radial-gradient(circle at top right, #1d1302 0%, transparent 70%),
      radial-gradient(circle at bottom left, #0b1f1d 0%, transparent 70%),
      radial-gradient(circle at bottom right, #0e2615 0%, transparent 70%) !important;
    background-color: #000000 !important;
    background-attachment: fixed !important;
    animation: auroraMove 50s ease infinite !important;
    z-index: -999 !important;
    pointer-events: none !important;
  }
  
  /* Sayfa ana zeminlerini şeffaflaştır ki arkadaki gradient görunsün */
  html, body, 
  #react-root, 
  #react-root > div, 
  main {
    background-color: transparent !important;
  }
  /* 2. SADECE POSTLARI AYIRAN YATAY ÇİZGİLERİ KALDIR */
  [data-testid="primaryColumn"],
  [data-testid="primaryColumn"] > div,
  [data-testid="cellInnerDiv"],
  [data-testid="cellInnerDiv"] > div {
    border-color: transparent !important;
    border-bottom: none !important; 
    border-top: none !important;
  }

  /* 3. ANA KOLONLARI SAYDAMLAŞTIR */
  header[role="banner"],
  [data-testid="primaryColumn"],
  [data-testid="sidebarColumn"] {
    background-color: transparent !important;
  }

  /* 4. SAĞ MENÜ KARTLARINI TAMAMEN SAYDAMLAŞTIR */
  [data-testid="sidebarColumn"] section,
  [data-testid="sidebarColumn"] section > div,
  [data-testid="sidebarColumn"] section > div > div,
  [data-testid="sidebarColumn"] aside,
  [data-testid="sidebarColumn"] aside > div,
  [data-testid="sidebarColumn"] aside > div > div {
    background-color: transparent !important;
  }

  /* 5. ÜST YAPIŞKAN MENÜLERİ (Sana Özel) TEMİZLE */
  [data-testid="primaryColumn"] > div:first-child,
  [data-testid="primaryColumn"] > div:first-child > div,
  [data-testid="primaryColumn"] > div:first-child > div > div,
  [data-testid="primaryColumn"] > div:first-child > div > div > div,
  [data-testid="sidebarColumn"] > div > div:first-child,
  [data-testid="sidebarColumn"] > div > div:first-child > div,
  [data-testid="sidebarColumn"] > div > div:first-child > div > div,
  [data-testid="sidebarColumn"] > div > div:first-child > div > div > div {
    background-color: transparent !important;
  }

  /* 7. ANA AKIŞ VE TWEET ZEMİNLERİNİ TEMİZLE */
  [data-testid="primaryColumn"] section,
  [data-testid="primaryColumn"] section > div,
  [data-testid="primaryColumn"] section > div > div,
  [data-testid="cellInnerDiv"],
  [data-testid="cellInnerDiv"] > div,
  article[data-testid="tweet"] {
    background-color: transparent !important;
  }

  /* 8. ARAMA ÇUBUĞU İÇİN ÖZEL TASARIM */
  form[role="search"] {
    background-color: #000000 !important;
    border: 1px solid #333333 !important;
    border-radius: 9999px !important;
  }
  form[role="search"] > div,
  form[role="search"] input {
    background-color: transparent !important;
  }
